/** Formats an amount in Costa Rican colones (whole units, no decimals). */
export function formatPrice(amount) {
  const whole = Math.round(Number(amount));
  const grouped = String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return `₡${grouped}`;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { formatPrice } from "../src/formatPrice.mjs";

test("formatPrice muestra colones sin decimales", () => {
  assert.equal(formatPrice(800), "₡800");
});

test("formatPrice separa miles con punto", () => {
  assert.equal(formatPrice(2500), "₡2.500");
  assert.equal(formatPrice(1_000_000), "₡1.000.000");
});

test("formatPrice redondea al entero más cercano", () => {
  assert.equal(formatPrice(99.6), "₡100");
});
